package com.sjd.scan;
import android.graphics.*;
public class Processor {
 public static float[] detect(Bitmap b){int w=420,h=Math.max(1,b.getHeight()*w/b.getWidth());if(h>640){h=640;w=b.getWidth()*h/b.getHeight();}Bitmap small=Bitmap.createScaledBitmap(b,w,h,true);int[] p=new int[w*h];small.getPixels(p,0,w,0,0,w,h);float[] q=detectPixels(p,w,h);if(small!=b)small.recycle();return q;}
 public static float[] detectPixels(int[] p,int w,int h){int n=w*h;int[] g=new int[n],hist=new int[256];for(int i=0;i<n;i++){int c=p[i];g[i]=(((c>>16)&255)*77+((c>>8)&255)*150+(c&255)*29)>>8;hist[g[i]]++;}double sum=0;for(int i=0;i<256;i++)sum+=i*hist[i];int count=0,t=150;double s=0,best=-1;for(int i=0;i<255;i++){count+=hist[i];s+=i*hist[i];if(count==0||count==n)continue;double d=s/count-(sum-s)/(n-count),v=(double)count*(n-count)*d*d;if(v>best){best=v;t=i;}}float[] win=null;double score=0;for(int threshold:new int[]{Math.min(230,Math.max(65,t)),Math.min(240,Math.max(110,t+25))}){boolean[] seen=new boolean[n];int[] queue=new int[n];for(int start=0;start<n;start++){if(seen[start]||g[start]<=threshold)continue;int a=0,z=1;queue[0]=start;seen[start]=true;int tl=start,tr=start,br=start,bl=start;while(a<z){int k=queue[a++],x=k%w,y=k/w;if(x+y<tl%w+tl/w)tl=k;if(x-y>tr%w-tr/w)tr=k;if(x+y>br%w+br/w)br=k;if(y-x>bl/w-bl%w)bl=k;for(int d=0;d<4;d++){int nx=x+(d==0?1:d==1?-1:0),ny=y+(d==2?1:d==3?-1:0);if(nx<0||ny<0||nx>=w||ny>=h)continue;int j=ny*w+nx;if(!seen[j]&&g[j]>threshold){seen[j]=true;queue[z++]=j;}}}if(z<n*.12)continue;float[] q={tl%w/(float)w,tl/w/(float)h,tr%w/(float)w,tr/w/(float)h,br%w/(float)w,br/w/(float)h,bl%w/(float)w,bl/w/(float)h};double area=area(q);int edges=0;for(int i=0;i<8;i++)if(q[i]<.015||q[i]>.985)edges++;double sc=area*(1-edges*.09);if(area>.13&&area<.97&&valid(q)&&sc>score){score=sc;win=q;}}}return win;}
 public static double area(float[] q){double s=0;for(int i=0;i<4;i++){int j=(i+1)%4;s+=q[2*i]*q[2*j+1]-q[2*j]*q[2*i+1];}return Math.abs(s)*.5;}
 public static boolean valid(float[] q){if(area(q)<.015)return false;for(int i=0;i<4;i++){int j=(i+1)%4,k=(i+2)%4;float cross=(q[j*2]-q[i*2])*(q[k*2+1]-q[j*2+1])-(q[j*2+1]-q[i*2+1])*(q[k*2]-q[j*2]);if(cross<=.0001)return false;}return true;}
 public static Bitmap warp(Bitmap src,float[] q){float[] from=q.clone();for(int i=0;i<8;i++)from[i]*=(i%2==0?src.getWidth():src.getHeight());int w=(int)Math.max(dist(from,0,1),dist(from,3,2)),h=(int)Math.max(dist(from,0,3),dist(from,1,2));float scale=(float)Math.min(Math.min(1,4000f/Math.max(w,h)),Math.sqrt(maxPixels()/(double)((long)w*h)));w=Math.max(20,(int)(w*scale));h=Math.max(20,(int)(h*scale));Matrix m=new Matrix();if(!m.setPolyToPoly(from,0,new float[]{0,0,w,0,w,h,0,h},0,4))throw new IllegalArgumentException();Bitmap out=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(out);c.drawColor(Color.WHITE);c.drawBitmap(src,m,new Paint(Paint.FILTER_BITMAP_FLAG|Paint.ANTI_ALIAS_FLAG));return out;}
 static double dist(float[] p,int a,int b){return Math.hypot(p[a*2]-p[b*2],p[a*2+1]-p[b*2+1]);}
 static int clamp(double v){return Math.max(0,Math.min(255,(int)v));}
 public static long maxPixels(){return Math.max(3000000,Math.min(10000000,Runtime.getRuntime().maxMemory()/40));}
 public static Bitmap enhance(Bitmap b,int[] controls){int w=b.getWidth(),h=b.getHeight();int[] pix=new int[w*h];b.getPixels(pix,0,w,0,0,w,h);Enhance.process(pix,w,h,controls);return Bitmap.createBitmap(pix,w,h,Bitmap.Config.ARGB_8888);}
}
